const j = items[0].json;
const d = j.data || j.record || j;
const lead = d.lead || d;
const email = lead.email || '';
const nombre = lead.nombre || 'Lead';
const score = lead.score ?? '-';
const clas = lead.clasificacion || '-';
const msg = (lead.mensaje || '').toString().slice(0, 400);
return [{
  json: {
    ...j,
    notifyTitle: clas === 'caliente' || j.event === 'lead.hot' ? '🔥 Lead CALIENTE' : '🆕 Nuevo lead',
    notifyText: `${nombre} · ${email} · score ${score}\n${msg}`,
    mailto: email && !String(email).includes('@pending.altivoxai') ? email : null
  }
}];
